if(!eth_seq.randomize()) `uvm_error("RAND","FAILED");
eth_seq.start(eth_sqr);
if(!ahb_seq.randomize()) `uvm_error("RAND","FAILED");
ahb_seq.start(ahb_sqr);
`uvm_info("v_seq2", "Sequence complete", UVM_HIGH)
